class Solution {
    public boolean isDigitorialPermutation(int n) {
        long[] fact = new long[10]; fact[0] = 1;
        for (int i = 1; i < 10; i++) fact[i] = fact[i-1]*i;
        char[] a = Integer.toString(n).toCharArray();
        Arrays.sort(a);
        do {
            if (a[0] == '0') continue;
            long num = Long.parseLong(new String(a)), sum = 0;
            for (char c : a) sum += fact[c - '0'];
            if (num == sum) return true;
        } while (nextPerm(a));
        return false;
    }
    private boolean nextPerm(char[] a) {
        int i = a.length - 2;
        while (i >= 0 && a[i] >= a[i+1]) i--;
        if (i < 0) return false;
        int j = a.length - 1;
        while (a[j] <= a[i]) j--;
        char t = a[i]; a[i] = a[j]; a[j] = t;
        for (int l = i+1, r = a.length-1; l < r; l++, r--) { t = a[l]; a[l] = a[r]; a[r] = t; }
        return true;
    }
}

