var isDigitorialPermutation = function(n) {
    const fact = [1]; for (let i = 1; i < 10; i++) fact[i] = fact[i-1]*i;
    const digs = String(n).split('').sort();
    const used = new Array(digs.length).fill(false);
    const cur = [];
    const go = () => {
        if (cur.length === digs.length) {
            if (cur[0] === '0') return false;
            const num = Number(cur.join(''));
            let sum = 0; for (const d of cur) sum += fact[+d];
            return num === sum;
        }
        for (let i = 0; i < digs.length; i++) {
            if (used[i] || (i > 0 && digs[i] === digs[i-1] && !used[i-1])) continue;
            used[i] = true; cur.push(digs[i]);
            if (go()) return true;
            cur.pop(); used[i] = false;
        }
        return false;
    };
    return go();
};

